			rStepBias=>rSearchNextStepTarget,rAGCMaxBias=>rMaxPosTest,bSucess=>);
		END_IF
// 程引模式下自跟踪拉偏
IF GVL.bStartTrack AND Axis1Remote.iMode=4 THEN
	Axis1Remote.bStartAutoTrack := TRUE;
	IF rAuToStepBias > rAutoTrackingBiasMax THEN
		rAuToStepBias := rAutoTrackingBiasMax;
	ELSIF rAuToStepBias < -rAutoTrackingBiasMax THEN
		rAuToStepBias := -rAutoTrackingBiasMax;
	ELSE
		rAuToStepBiasTemp:=0.02*AutoTrackingCal.rDirSenFac*AutoTrackingCal.rChanUe;
		rAuToStepBias:=rAuToStepBias+AutoTrackingCal.rDirSenFac*rKAuToStepBias*AutoTrackingCal.rChanUe/1000.0;
	END_IF
ELSIF NOT GVL.bStartTrack AND Axis1Remote.iMode=4 THEN
	IF 	rAuToStepBias>0 THEN//关闭自跟踪后自跟踪拉偏量逐渐归0
		rAuToStepBias:=rAuToStepBias-rAutoStep;
	ELSIF rAuToStepBias<0 THEN
		rAuToStepBias:=rAuToStepBias+rAutoStep;
	ELSE
		rAuToStepBias:=0;
	END_IF

	IF Modbus_Slave.rBias_1>rStepBias THEN
		rStepBias:=rStepBias+rStep;
		IF rStepBias>=Modbus_Slave.rBias_1 THEN
			rStepBias:=Modbus_Slave.rBias_1;
		END_IF
	ELSIF Modbus_Slave.rBias_1<rStepBias THEN
		rStepBias:=rStepBias-rStep;
		IF rStepBias<=Modbus_Slave.rBias_1 THEN
			rStepBias:=Modbus_Slave.rBias_1;
		END_IF
	END_IF
	rAuToStepBiasTemp:=0;
ELSIF GVL.bStartTrack AND Axis1Remote.iMode=2 THEN
	Axis1Remote.bStartAutoTrack := TRUE;
	Axis1Remote.rChanU := AutoTrackingCal.rChanUe;
ELSE
	Axis1Remote.bStartAutoTrack := FALSE;	
	rAuToStepBias:=0;
	rStepBias:=0;
	rAuToStepBiasTemp:=0;
END_IF

//本控自跟踪
IF GVL.bStartLocalAutoTrack AND Axis1Local.iMode = 4 THEN
	Axis1Local.bStartAutoTrack := TRUE;
	Axis1Local.rChanU := AutoTrackingCal.rChanUeLocal;
ELSE
	Axis1Local.bStartAutoTrack := FALSE;
END_IF

//拉偏
Axis1Remote.rPIDCmdPos:=RealTimePosCal.rInterElPos+rStepBias+rAuToStepBias+rSearchNextStepTarget+SECURITYCHECK.el_out+rAuToStepBiasTemp;
//限位
IF Axis1Remote.rPIDCmdPos<93 THEN
	Axis1Remote.rPIDCmdPos:=93;
ELSIF Axis1Remote.rPIDCmdPos>180 THEN
	Axis1Remote.rPIDCmdPos:=180;
END_IF

Axis1_Ctrl(sLocal:=Axis1Local, sCtrl:=Axis1Remote, sStatus:=Axis1Status, sVisible:=Axis1Visible, rRealPos:=rFctPosReal_1, rPosLimK:=0.34);

baseline.declaration:
PROGRAM Ti_ctrl_1
VAR
	Axis3_Ctrl:Ti_Ctrl_FB;
	bRemote2LocalStop:BOOL;
	bLocal2RemoteStop:BOOL;
	Error:INT;

	Axis3Limit_pos:REAL;//正软限位
	Axis3Limit_Neg:REAL;//负软限位

	bRTriger:Standard.R_TRIG;//本控上升沿
	bFTriger:Standard.F_TRIG;//远控下降沿
	Stop3_Count: INT;
	bStop_3: BOOL;

	//指向模式自跟踪
	rPosModeStepBias:LREAL;//指向模式自跟踪拉偏累计值
	rPosModeStep:LREAL:=0.005;//指向模式自跟踪步长，积分用
	rStepBiasMax:LREAL:=2;//指向模式拉偏最大值

	//程引拉偏
	rStepBias:LREAL;//步进拉偏累计值
// 	rStep:LREAL:=0.0002;//步长，与控制周期有关，1ms周期对应1秒内累积0.0002*1000=0.2°
// 	rStep:LREAL:=0.01;//步长，与控制周期有关，50ms周期对应1秒内累积0.01*20=0.2°
	rStep:LREAL:=0.004;//步长，与控制周期有关，20ms周期对应1秒内累积0.004*50=0.2°

	//自跟踪拉偏
	rAuToStepBias:LREAL;//步进拉偏累计值
// 	rAutoStep:LREAL:=0.005;//步长
	rAutoStep:LREAL:=0.01;//步长
	TbAutoTrigger:Standard.F_TRIG;//自跟踪关闭的下降沿
	RbAutoTrigger:Standard.R_TRIG;//自跟踪开启的上升沿

	rAutoTrackingBiasMax:LREAL:=300;//自跟踪拉偏最大值
	rLocalInitPosModeSpeed: REAL;
	rRemoteInitPosModeSpeed: REAL;
	iCountOffAuto: INT;

	iCasePBAutoTrack:INT:=2;//程序引导自跟踪切换 
// 	rKAuToStepBias:LREAL:=0.25;
	rKAuToStepBias:LREAL:=0.16;
	bVisError:BOOL; //报错可视化标识
END_VAR

baseline.implementation:
IF GVL.Error_code <> 0 THEN
	bVisError := TRUE;
ELSE
	bVisError := FALSE;
END_IF
(*
//远控轴参量赋值
Axis2Remote.iMode:=Modbus_Slave.iMode_2;
Axis2Remote.rVelCmd:=Modbus_Slave.rVelcmd_2;
Axis2Remote.rPosCmd:=Modbus_Slave.rPosCmd_2;
Axis2Remote.rP:=Modbus_Slave.rP_2;
Axis2Remote.rI:=Modbus_Slave.rI_2;
Axis2Remote.rD:=Modbus_Slave.rD_2;
Axis2Remote.rPIDThre:=Modbus_Slave.rThreshold_2;
Axis2Remote.rAcceleration:=Modbus_Slave.rAcceleration_2;
Axis2Remote.rDeceleration:=Modbus_Slave.rDeceleration_2;
Axis2Remote.rVel_Limit:=Modbus_Slave.rVelLim_2;
*)
// 倾斜轴状态写入
Axis3Status.Error := GVL.bTiStsBit3;
Axis3Status.ErrorID := GVL.eTiErrorcode;
Axis3Status.bServo_Enable := GVL.bTiStsBit0 AND GVL.bTiStsBit1 AND GVL.bTiStsBit2;
Axis3Status.bBrake := NOT (GVL.bTiStsBit0 AND GVL.bTiStsBit1 AND GVL.bTiStsBit2);
Axis3Status.Disabled := NOT (GVL.bTiStsBit0 AND GVL.bTiStsBit1 AND GVL.bTiStsBit2);
Axis3Remote.rSoft_limit_Negative:=-190;Axis3Remote.rSoft_limit_Postive:=190;
Axis3Local.rSoft_limit_Negative:=-190;Axis3Local.rSoft_limit_Postive:=190;

//速度的写入
rFctVelReal_3:=DINT_TO_REAL(diTiActVel)/524288.0*360.0;
//位置的写入，方位0对应编码器0，所以实际方位是：-1*编码器值
//rFctPosReal_3:=DINT_TO_REAL(diTiActPos)/524288.0*360.0-11.413-0.08;
rFctPosReal_3:=DINT_TO_REAL(diTiActPos)/524288.0*360.0;
//软限位控制
Axis3Limit_pos:=190;
Axis3Limit_Neg:=-190;
IF Axis3Remote.rPosCmd>Axis3Limit_pos THEN
	Axis3Remote.rPosCmd:=190;
ELSIF Axis3Remote.rPosCmd<Axis3Limit_Neg THEN
	 Axis3Remote.rPosCmd:=-190;  
END_IF

IF Axis3Local.rPosCmd>Axis3Limit_pos THEN
	Axis2Local.rPosCmd:=190;
ELSIF Axis3Local.rPosCmd<Axis3Limit_Neg THEN
	 Axis3Local.rPosCmd:=-190;  
END_IF

//停止标志符号判断
IF  ABS(rFctVelReal_3)<0.035 THEN
	Stop3_Count:=Stop3_Count+1;
	IF Stop3_Count>100 THEN
		Stop3_Count:=101;
		bStop_3:=TRUE;;
	END_IF
ELSE
	Stop3_Count:=0;
	bStop_3:=FALSE;
END_IF
Axis3Status.Moving := NOT bStop_3;
//PID使能赋值
IF Axis3Remote.iMode=2 OR Axis3Remote.iMode=4 THEN
	Axis3Remote.bPIDEnable:=TRUE;
ELSE
	Axis3Remote.bPIDEnable:=FALSE;
END_IF

//本远控逻辑保护
//远控切本控逻辑保护
bRTriger(CLK:=GVL.bLocalCtrl);
bFTriger(CLK:=GVL.bLocalCtrl);

IF Axis3Status.bServo_Enable AND (bRTriger.Q ) THEN//如果速度不为0且本控发生切换，则减速停止标识为True
	bRemote2LocalStop:=TRUE;
END_IF
IF bRemote2LocalStop  THEN //若减速停止标识符为True 

	IF  bStop_3=TRUE THEN//且电机速度不为0 开始减速 减速完成后下使能，下使能完成后复位标识符复位
		Axis3Local.iMode:=0;
		Axis3Remote.iMode:=0;
		IF Axis3Status.bServo_Enable=FALSE THEN
			bRemote2LocalStop:=FALSE;
		END_IF
	ELSE
		Axis3Remote.iMode:=7;
	END_IF
END_IF

//本控切远控
IF Axis3Status.bServo_Enable AND (bFTriger.Q ) THEN//如果速度不为0且本控发生切换，则减速停止标识为True
	bLocal2RemoteStop:=TRUE;
END_IF
IF bLocal2RemoteStop  THEN //若减速停止标识符为True 

	IF  bStop_3=TRUE THEN//且电机速度不为0 开始减速 减速完成后下使能，下使能完成后复位标识符复位
		Axis3Local.iMode:=0;
		Axis3Remote.iMode:=0;
		IF Axis3Status.bServo_Enable=FALSE THEN
			bLocal2RemoteStop:=FALSE;
		END_IF
	ELSE
		Axis3Remote.iMode:=7;
		Axis3Local.iMode:=7;
	END_IF
END_IF
(*
//自跟踪
IF GVL.bStartTrack THEN
	Axis2Remote.bStartAutoTrack := TRUE;
	Axis2Remote.rChanU := -AutoTrackingCal.rChanUa;
ELSE
	Axis2Remote.bStartAutoTrack := FALSE;	
	Axis2Remote.rChanU := 0;
END_IF
//拉偏
Axis2Remote.rPIDCmdPos:=RealTimePosCal.rInterAzPos+Modbus_Slave.rBias_2;
*)
//限位
IF Axis3Remote.rPIDCmdPos<-190 THEN
	Axis3Remote.rPIDCmdPos:=-190;
ELSIF Axis3Remote.rPIDCmdPos>190 THEN
	Axis3Remote.rPIDCmdPos:=190;
END_IF

Axis3_Ctrl(sLocal:=Axis3Local, sCtrl:=Axis3Remote, sStatus:=Axis3Status, sVisible:=Axis3Visible, rRealPos:=rFctPosReal_3, rPosLimK:=0.34);

baseline.declaration:
FUNCTION_BLOCK Az_Ctrl_FB
VAR_INPUT
	sLocal:AxisCrtlStruct;
	sCtrl:AxisCrtlStruct;
	sStatus:AxisStatus;
	sVisible:AxisVisible;
	rRealPos:REAL;
	rPosLimK:REAL;
END_VAR
VAR_OUTPUT
	logicError:INT;
END_VAR
VAR
	VelPID_1:PID;
	VelPID_2:PID;
	VelPID_3:PID;
	vpid1:vpid;
	TON_0:TON;
	bTick:BOOL;
	tr:BOOL;
	icount1:INT := 0;
	icount2:INT := 0;
	icount3:INT := 0;
	bfin1:BOOL;
	bfin2:BOOL;
	istate:INT:=0;
	icount:INT:=0;
END_VAR

baseline.implementation:
// 下电时复位控制字bit8
IF sStatus.Disabled OR(NOT sStatus.Moving)THEN
	bAzCtrlBit8 := FALSE;
END_IF

//	错误复位功能
IF GVL.bError_Reset THEN
	sCtrl.iMode:=6;
	sLocal.iMode:=6;
	GVL.Error_code:=0;
END_IF
IF GVL.Error_code =0 THEN
	GVL.bError_Reset:=FALSE;
END_IF

/////////心跳报错清除/////////
IF GVL.eAzErrorcode = 16#8130 AND NOT tr THEN
	GVL.bAzCtrlBit7 := TRUE;
	tr:=TRUE;
	istate:=0;
	icount:=0;
	// 写入下电控制字
	GVL.bAzCtrlBit3 := FALSE;
	GVL.bAzCtrlBit0 := FALSE;
	GVL.bAzCtrlBit1 := FALSE;
	GVL.bAzCtrlBit2 := FALSE;
END_IF
IF tr THEN
	icount1 := icount1 + 1;
END_IF
IF icount1 > 101 THEN
	icount1 := 0;
	tr := FALSE;
	GVL.bAzCtrlBit7 := FALSE;
	bfin1 := TRUE;
END_IF
IF bfin1 THEN
	icount2 := icount2 + 1;
END_IF
IF icount2 > 101 THEN
	bfin1 := FALSE;
	icount2 := 0;
END_IF
/////////////////////////////

IF GVL.Error_code=0 AND GVL.eAzErrorcode = 0 AND NOT GVL.bAzCtrlBit7  AND NOT tr AND NOT bfin1 AND NOT bfin2 THEN
	IF GVL.bLocalCtrl=FALSE THEN //远控
		IF sCtrl.iMode <> 1 THEN
			istate:=0;
			icount:=0;
		END_IF
		CASE sCtrl.iMode OF
			MODES.powerOff: // 下电
				IF NOT sStatus.Disabled THEN
					IF sStatus.Moving THEN // 运动中，先停止运动
						GVL.diAzTargetVel := 0;
						bAzCtrlBit8 := TRUE;
					ELSE
						// 写入下电控制字
						GVL.bAzCtrlBit3 := FALSE;
						GVL.bAzCtrlBit0 := FALSE;
						GVL.bAzCtrlBit1 := FALSE;
						GVL.bAzCtrlBit2 := FALSE;
					END_IF
				END_IF

				vpid1(rKpbase:=1, rKibase:=0.01, rKpMax:=1, rKiMax:=0.01, rVelThreshold:=10,rTarget:=sCtrl.rPIDCmdPos,rFeedback:=rRealPos,rPosLimPositive:=sCtrl.rSoft_limit_Postive,
							rPosLimNegitive:=sCtrl.rSoft_limit_Negative,
								bPIDEnable:=sCtrl.bPIDEnable,rVelLim:=sCtrl.rVel_Limit,rKpScale:=0.02,rKiScale:=0.005,rElPos:=GVL.rFctPosReal_1-90,
								iThrehold:=sCtrl.rPIDThre,rPIDOutDir=>sCtrl.rPIDCmdVel);
			MODES.powerOn:  // 上电
				IF sStatus.Disabled THEN
					// 目标速度清零
					GVL.diAzTargetVel := 0;
					IF GVL.siAzMode <> 3 THEN // 上电时模式默认为3，速度模式
						GVL.siAzMode := 3;
					END_IF
					IF siAzMode = 3 THEN
						CASE istate OF
							0:
								GVL.bAzCtrlBit1 := TRUE;
								GVL.bAzCtrlBit2 := TRUE;
								icount := icount + 1;
								IF icount = 20 THEN
									icount:=0;
									istate:=1;
								END_IF
							1:
								GVL.bAzCtrlBit0 := TRUE;
								icount := icount + 1;
								IF icount = 20 THEN
									icount:=0;
									istate:=2;
								END_IF
							2:
								GVL.bAzCtrlBit3 := TRUE;
						END_CASE
					END_IF
				ELSE
					IF sStatus.Moving THEN
						GVL.diAzTargetVel := 0;
						bAzCtrlBit8 := TRUE;
					ELSE
						bAzCtrlBit8 := FALSE;
					END_IF
				END_IF
			MODES.positionMode: // 远控指向模式
				IF NOT sStatus.Disabled THEN
					IF sCtrl.bStartAutoTrack THEN
						//自跟踪模式下，由误差电压直接驱动
						VelPID_1(rTarget:=sCtrl.rChanU + rRealPos,
								rFeedback:=rRealPos,
								rPosLimPositive:=sCtrl.rSoft_limit_Postive,
								rPosLimNegative:=sCtrl.rSoft_limit_Negative,
								rVelLim:=sCtrl.rVel_Limit,
								rKp:=1,//自跟踪PI系数3,0.02
								rKi:=0,
								rKd:=0,
								bPIDEnable:=sCtrl.bPIDEnable,
								iThreshold:= -1,
								rPIDOutput=>sCtrl.rPIDCmdVel);							
					ELSE
						//PID计算速度指令
						VelPID_1(rTarget:=sCtrl.rPosCmd,
							rFeedback:=rRealPos,
							rVelLim:=sCtrl.Pos_Vel,
							rPosLimPositive:=sCtrl.rSoft_limit_Postive,
							rPosLimNegative:=sCtrl.rSoft_limit_Negative,
							rKp:=0.6,//程引PI系数低带：1,0.002  高带：3,0.02
							rKi:=0,
							rKd:=0,
							bPIDEnable:=sCtrl.bPIDEnable,
							iThreshold:=sCtrl.rPIDThre,
							rPIDOutput=>sCtrl.rPIDCmdVel);
					END_IF
					GVL.diAzTargetVel := REAL_TO_DINT(sCtrl.rPIDCmdVel * 524288 / 360);
					GVL.diAzTargetAcc := REAL_TO_UDINT(12 * 524288 / 360);   //加速度
					GVL.diAzTargetDec := REAL_TO_UDINT(12 * 524288 / 360);   //减速度
				END_IF
			MODES.velocityMode://手控速度模式-远控模式
				IF NOT sStatus.Disabled THEN
					IF ABS(sCtrl.rVelCmd) <= sCtrl.rVel_Limit THEN
						GVL.diAzTargetVel := REAL_TO_DINT(sCtrl.rVelCmd * 524288 / 360);
					ELSIF sCtrl.rVelCmd > sCtrl.rVel_Limit THEN
						GVL.diAzTargetVel := REAL_TO_DINT(sCtrl.rVel_Limit * 524288 / 360);
					ELSE
						GVL.diAzTargetVel := REAL_TO_DINT(-sCtrl.rVel_Limit * 524288 / 360);
					END_IF
					GVL.diAzTargetAcc := REAL_TO_UDINT(sCtrl.rAcceleration * 524288 / 360);   //加速度
					GVL.diAzTargetDec := REAL_TO_UDINT(sCtrl.rDeceleration * 524288 / 360);   //减速度
				END_IF
			MODES.programBootMode://PID速度模式-正常模式 程引
				IF NOT sStatus.Disabled THEN
					IF sCtrl.bStartAutoTrack THEN
						(*
						//自跟踪模式下，由误差电压直接驱动
						VelPID_3(rTarget:=sCtrl.rChanU + rRealPos,
								rFeedback:=rRealPos,
								rPosLimPositive:=sCtrl.rSoft_limit_Postive,
								rPosLimNegative:=sCtrl.rSoft_limit_Negative,
								rVelLim:=sCtrl.rVel_Limit,
								rKp:=sCtrl.rP_AutoTrack,//自跟踪PI系数3,0.02
								rKi:=sCtrl.rI_AutoTrack,
								rKd:=sCtrl.rD,
								bPIDEnable:=sCtrl.bPIDEnable,
								iThreshold:= -1,
								rPIDOutput=>sCtrl.rPIDCmdVel);
								*)
						vpid1(rKpbase:=Persistentvars.rAzKpBase, rKibase:=Persistentvars.rAzKiBase, rKpMax:=Persistentvars.rAzKpMax, rKiMax:=Persistentvars.rAzKiMax, rVelThreshold:=Persistentvars.rAzThre,rTarget:=sCtrl.rPIDCmdPos,rFeedback:=rRealPos,rPosLimPositive:=sCtrl.rSoft_limit_Postive,
							rPosLimNegitive:=sCtrl.rSoft_limit_Negative,
								bPIDEnable:=sCtrl.bPIDEnable,rVelLim:=sCtrl.rVel_Limit,rKpScale:=Persistentvars.rAzKpscale,rKiScale:=Persistentvars.rAzKiscale,rElPos:=GVL.rFctPosReal_1-90,
								iThrehold:=sCtrl.rPIDThre,rPIDOutDir=>sCtrl.rPIDCmdVel);							
					ELSE
						//PID计算速度指令
						(*
						VelPID_3(rTarget:=sCtrl.rPIDCmdPos,
							rFeedback:=rRealPos,
							rVelLim:=sCtrl.rVel_Limit,
							rPosLimPositive:=sCtrl.rSoft_limit_Postive,
							rPosLimNegative:=sCtrl.rSoft_limit_Negative,
							rKp:=sCtrl.rP,//程引PI系数地带：1,0.002  高带：3,0.02
							rKi:=sCtrl.rI,
							rKd:=sCtrl.rD,
							bPIDEnable:=sCtrl.bPIDEnable,
							iThreshold:=sCtrl.rPIDThre,
							rPIDOutput=>);
							*)
						vpid1(rKpbase:=Persistentvars.rAzKpBase, rKibase:=Persistentvars.rAzKiBase, rKpMax:=Persistentvars.rAzKpMax, rKiMax:=Persistentvars.rAzKiMax, rVelThreshold:=Persistentvars.rAzThre,rTarget:=sCtrl.rPIDCmdPos,rFeedback:=rRealPos,rPosLimPositive:=sCtrl.rSoft_limit_Postive,
							rPosLimNegitive:=sCtrl.rSoft_limit_Negative,
								bPIDEnable:=sCtrl.bPIDEnable,rVelLim:=sCtrl.rVel_Limit,rKpScale:=Persistentvars.rAzKpscale,rKiScale:=Persistentvars.rAzKiscale,rElPos:=GVL.rFctPosReal_1-90,
								iThrehold:=sCtrl.rPIDThre,rPIDOutDir=>sCtrl.rPIDCmdVel);

					END_IF
					GVL.diAzTargetVel := REAL_TO_DINT(sCtrl.rPIDCmdVel * 524288 / 360);
					GVL.diAzTargetAcc := REAL_TO_UDINT(sCtrl.rAcceleration * 524288 / 360);   //加速度
					GVL.diAzTargetDec := REAL_TO_UDINT(sCtrl.rDeceleration * 524288 / 360);   //减速度
				END_IF
			MODES.reset://重置
				IF NOT sStatus.Disabled THEN
					IF sStatus.Moving THEN
						GVL.diAzTargetVel := 0;
						bAzCtrlBit8 := TRUE;
					ELSE
						bAzCtrlBit8 := FALSE;
					END_IF
				END_IF
			MODES.halt://待机
				IF NOT sStatus.Disabled THEN
					IF sStatus.Moving THEN
						GVL.diAzTargetVel := 0;
						bAzCtrlBit8 := TRUE;
					ELSE
						bAzCtrlBit8 := FALSE;
					END_IF
				END_IF

		END_CASE
	ELSE // 本控
		IF sLocal.iMode <> 1 THEN
			istate:=0;
			icount:=0;
		END_IF
		CASE sLocal.iMode OF
			MODES.powerOff: // 下电
				IF NOT sStatus.Disabled THEN
					IF sStatus.Moving THEN // 运动中，先停止运动
						GVL.diAzTargetVel := 0;
						bAzCtrlBit8 := TRUE;
					ELSE
						// 写入下电控制字
						GVL.bAzCtrlBit3 := FALSE;
						GVL.bAzCtrlBit0 := FALSE;
						GVL.bAzCtrlBit1 := FALSE;
						GVL.bAzCtrlBit2 := FALSE;
					END_IF
				END_IF
			MODES.powerOn:  // 上电
				IF sStatus.Disabled THEN
					// 目标速度清零
					GVL.diAzTargetVel := 0;
					IF GVL.siAzMode <> 3 THEN // 上电时模式默认为3，速度模式
						GVL.siAzMode := 3;
					END_IF
					IF siAzMode = 3 THEN
						CASE istate OF
							0:
								GVL.bAzCtrlBit1 := TRUE;
								GVL.bAzCtrlBit2 := TRUE;
								icount := icount + 1;
								IF icount = 20 THEN
									icount:=0;
									istate:=1;
								END_IF
							1:
								GVL.bAzCtrlBit0 := TRUE;
								icount := icount + 1;
								IF icount = 20 THEN
									icount:=0;
									istate:=2;
								END_IF
							2:
								GVL.bAzCtrlBit3 := TRUE;
						END_CASE
					END_IF
				ELSE
					IF sStatus.Moving THEN
						GVL.diAzTargetVel := 0;
						bAzCtrlBit8 := TRUE;
					ELSE
						bAzCtrlBit8 := FALSE;
					END_IF
				END_IF
			MODES.velocityMode://手控速度模式-本控模式
				IF NOT sStatus.Disabled THEN
					IF ABS(sLocal.rVelCmd) <= sLocal.rVel_Limit THEN
						GVL.diAzTargetVel := REAL_TO_DINT(sLocal.rVelCmd * 524288 / 360);
					ELSIF sLocal.rVelCmd > sLocal.rVel_Limit THEN
						GVL.diAzTargetVel := REAL_TO_DINT(sLocal.rVel_Limit * 524288 / 360);
					ELSE
						GVL.diAzTargetVel := REAL_TO_DINT(-sLocal.rVel_Limit * 524288 / 360);
					END_IF
					GVL.diAzTargetAcc := REAL_TO_UDINT(sLocal.rAcceleration * 524288 / 360);   //加速度
					GVL.diAzTargetDec := REAL_TO_UDINT(sLocal.rDeceleration * 524288 / 360);   //减速度
				END_IF
			MODES.programBootMode://本控位置模式
				IF NOT sStatus.Disabled THEN
					IF NOT sLocal.bPIDEnable THEN
						GVL.diAzTargetVel := 0;							
					ELSE
						IF NOT slocal.bStartAutoTrack THEN
							//PID计算速度指令
							 VelPID_2(rTarget:=sLocal.rPosCmd,
									 rFeedback:=rRealPos,
									 rPosLimPositive:=sLocal.rSoft_limit_Postive,//软限位
									 rPosLimNegative:=sLocal.rSoft_limit_Negative,
									 rKp:=0.6,
									 rKi:=0,
									 rKd:=0,
									 iThreshold:=sLocal.rPIDThre,
									 bPIDEnable:=sLocal.bPIDEnable,
									 rVelLim:=sLocal.Pos_Vel,
									 rPIDOutput=>sLocal.rPIDCmdVel);//普通PID
						ELSE
							//PID计算速度指令
							 VelPID_2(rTarget:=sLocal.rChanU + rRealPos,
								rFeedback:=rRealPos,
								rPosLimPositive:=sLocal.rSoft_limit_Postive,
								rPosLimNegative:=sLocal.rSoft_limit_Negative,
								rVelLim:=sLocal.rVel_Limit,
								rKp:=1,//自跟踪PI系数3,0.02
								rKi:=0,
								rKd:=0,
								bPIDEnable:=sLocal.bPIDEnable,
								iThreshold:= -1,
								rPIDOutput=>sLocal.rPIDCmdVel);//普通PID
						END_IF

					END_IF
					GVL.diAzTargetVel := REAL_TO_DINT(sLocal.rPIDCmdVel * 524288 / 360);
					GVL.diAzTargetAcc := REAL_TO_UDINT(12 * 524288 / 360);   //加速度
					GVL.diAzTargetDec := REAL_TO_UDINT(12 * 524288 / 360);   //减速度
				END_IF
			MODES.reset://重置
			// 是否需要
			MODES.halt://待机
				IF NOT sStatus.Disabled THEN
					IF sStatus.Moving THEN
						GVL.diAzTargetVel := 0;
						bAzCtrlBit8 := TRUE;
					ELSE
						bAzCtrlBit8 := FALSE;
					END_IF
				END_IF

		END_CASE
	END_IF
ELSIF GVL.Error_code<>0 AND GVL.eAzErrorcode = 0 AND NOT GVL.bAzCtrlBit7  AND NOT tr AND NOT bfin1 AND NOT bfin2 THEN
	// 出现错误，轴停止运动
	GVL.diAzTargetVel := 0;
	bAzCtrlBit8 := TRUE;
	TON_0(IN:=bAzCtrlBit8,PT:=T#1S,Q=>,ET=>);//判断stop0执行是否超时,若超时强制下电（手动复位）
	IF TON_0.Q THEN
		bTick:=TRUE;
	END_IF
	IF bTick AND sStatus.Moving THEN // 超时强制下电
		// 写入下电控制字
		GVL.bAzCtrlBit3 := FALSE;
		GVL.bAzCtrlBit0 := FALSE;
		GVL.bAzCtrlBit1 := FALSE;
		GVL.bAzCtrlBit2 := FALSE;
	END_IF
END_IF

baseline.declaration:
FUNCTION_BLOCK El_Ctrl_FB
VAR_INPUT
	sLocal:AxisCrtlStruct;
	sCtrl:AxisCrtlStruct;
	sStatus:AxisStatus;
	sVisible:AxisVisible;
	rRealPos:REAL;
	rPosLimK:REAL;
END_VAR
VAR_OUTPUT
	logicError:INT;
END_VAR
VAR
	VelPID_1:PID;
	VelPID_2:PID;
	VelPID_3:PID;
	vpid1:vpid;
	TON_0:TON;
	bTick:BOOL;
	tr:BOOL;
	icount1:INT := 0;
	icount2:INT := 0;
	icount3:INT := 0;
	bfin1:BOOL;
	bfin2:BOOL;
	istate:INT:=0;
	icount:INT:=0;
END_VAR

baseline.implementation:
// 下电时复位控制字bit8
IF sStatus.Disabled OR (NOT sStatus.Moving) THEN
	bElCtrlBit8 := FALSE;
END_IF

//	错误复位功能
IF GVL.bError_Reset THEN
	sCtrl.iMode:=6;
	sLocal.iMode:=6;
	GVL.Error_code:=0;
END_IF
IF GVL.Error_code =0 THEN
	GVL.bError_Reset:=FALSE;
END_IF

/////////心跳报错清除/////////
IF GVL.eElErrorcode = 16#8130 AND NOT tr THEN
	GVL.bElCtrlBit7 := TRUE;
	tr:=TRUE;
	istate:=0;
	icount:=0;
	// 写入下电控制字
	GVL.bElCtrlBit3 := FALSE;
	GVL.bElCtrlBit0 := FALSE;
	GVL.bElCtrlBit1 := FALSE;
	GVL.bElCtrlBit2 := FALSE;	
END_IF
IF tr THEN
	icount1 := icount1 + 1;
END_IF
IF icount1 > 101 THEN
	icount1 := 0;
	tr := FALSE;
	GVL.bElCtrlBit7 := FALSE;
	bfin1 := TRUE;
END_IF
IF bfin1 THEN
	icount2 := icount2 + 1;
END_IF
IF icount2 > 101 THEN
	bfin1 := FALSE;
	icount2 := 0;
END_IF
//////////////////////////////

IF GVL.Error_code=0 AND GVL.eElErrorcode = 0 AND NOT GVL.bElCtrlBit7  AND NOT tr AND NOT bfin1 AND NOT bfin2 THEN
	IF GVL.bLocalCtrl=FALSE THEN //远控
		IF sCtrl.iMode <> 1 THEN
			istate:=0;
			icount:=0;
		END_IF
		CASE sCtrl.iMode OF
			MODES.powerOff: // 下电
				IF NOT sStatus.Disabled THEN
					IF sStatus.Moving THEN // 运动中，先停止运动
						GVL.diElTargetVel := 0;
						bElCtrlBit8 := TRUE;
					ELSE
						// 写入下电控制字
						GVL.bElCtrlBit3 := FALSE;
						GVL.bElCtrlBit0 := FALSE;
						GVL.bElCtrlBit1 := FALSE;
						GVL.bElCtrlBit2 := FALSE;
					END_IF
				END_IF

				vpid1(rKpbase:=1, rKibase:=0.01, rKpMax:=1, rKiMax:=0.01, rVelThreshold:=10,rTarget:=sCtrl.rPIDCmdPos,rFeedback:=rRealPos,rPosLimPositive:=sCtrl.rSoft_limit_Postive,
							rPosLimNegitive:=sCtrl.rSoft_limit_Negative,
								bPIDEnable:=sCtrl.bPIDEnable,rVelLim:=sCtrl.rVel_Limit,rKpScale:=0.02,rKiScale:=0.005,rElPos:=GVL.rFctPosReal_1-90,
								iThrehold:=sCtrl.rPIDThre,rPIDOutDir=>sCtrl.rPIDCmdVel);
			MODES.powerOn:  // 上电
				IF sStatus.Disabled THEN
					// 目标速度清零
					GVL.diElTargetVel := 0;
					IF GVL.siElMode <> 3 THEN // 上电时模式默认为3，速度模式
						GVL.siElMode := 3;
					END_IF
					IF siElMode = 3 THEN
						CASE istate OF
							0:
								GVL.bElCtrlBit1 := TRUE;
								GVL.bElCtrlBit2 := TRUE;
								icount := icount + 1;
								IF icount = 20 THEN
									icount:=0;
									istate:=1;
								END_IF
							1:
								GVL.bElCtrlBit0 := TRUE;
								icount := icount + 1;
								IF icount = 20 THEN
									icount:=0;
									istate:=2;
								END_IF
							2:
								GVL.bElCtrlBit3 := TRUE;
						END_CASE
					END_IF
				ELSE
					IF sStatus.Moving THEN
						GVL.diElTargetVel := 0;
						bElCtrlBit8 := TRUE;
					ELSE
						bElCtrlBit8 := FALSE;
					END_IF
				END_IF
			MODES.positionMode: // 远控指向模式
				IF NOT sStatus.Disabled THEN
					IF sCtrl.bStartAutoTrack THEN
						//自跟踪模式下，由误差电压直接驱动
						VelPID_1(rTarget:=sCtrl.rChanU + rRealPos,
								rFeedback:=rRealPos,
								rPosLimPositive:=sCtrl.rSoft_limit_Postive,
								rPosLimNegative:=sCtrl.rSoft_limit_Negative,
								rVelLim:=sCtrl.rVel_Limit,
								rKp:=1,//自跟踪PI系数3,0.02
								rKi:=0,
								rKd:=0,
								bPIDEnable:=sCtrl.bPIDEnable,
								iThreshold:= -1,
								rPIDOutput=>sCtrl.rPIDCmdVel);							
					ELSE
						//PID计算速度指令
						VelPID_1(rTarget:=sCtrl.rPosCmd,
							rFeedback:=rRealPos,
							rVelLim:=sCtrl.Pos_Vel,
							rPosLimPositive:=sCtrl.rSoft_limit_Postive,
							rPosLimNegative:=sCtrl.rSoft_limit_Negative,
							rKp:=0.7,//程引PI系数地带：1,0.002  高带：3,0.02
							rKi:=0,
							rKd:=0,
							bPIDEnable:=sCtrl.bPIDEnable,
							iThreshold:=sCtrl.rPIDThre,
							rPIDOutput=>sCtrl.rPIDCmdVel);
					END_IF
					GVL.diElTargetVel := REAL_TO_DINT(sCtrl.rPIDCmdVel * 524288 / 360);
					GVL.diElTargetAcc := REAL_TO_UDINT(9 * 524288 / 360);   //加速度
					GVL.diElTargetDec := REAL_TO_UDINT(9 * 524288 / 360);   //减速度
				END_IF
			MODES.velocityMode://手控速度模式-远控模式
				IF NOT sStatus.Disabled THEN
					IF ABS(sCtrl.rVelCmd) <= sCtrl.rVel_Limit THEN
						GVL.diElTargetVel := REAL_TO_DINT(sCtrl.rVelCmd * 524288 / 360);
					ELSIF sCtrl.rVelCmd > sCtrl.rVel_Limit THEN
						GVL.diElTargetVel := REAL_TO_DINT(sCtrl.rVel_Limit * 524288 / 360);
					ELSE
						GVL.diElTargetVel := REAL_TO_DINT(-sCtrl.rVel_Limit * 524288 / 360);
					END_IF
					GVL.diElTargetAcc := REAL_TO_UDINT(sCtrl.rAcceleration * 524288 / 360);   //加速度
					GVL.diElTargetDec := REAL_TO_UDINT(sCtrl.rDeceleration * 524288 / 360);   //减速度
				END_IF
			MODES.programBootMode://PID速度模式-正常模式 程引
				IF NOT sStatus.Disabled THEN
					IF sCtrl.bStartAutoTrack THEN
						(*
						//自跟踪模式下，由误差电压直接驱动
						VelPID_3(rTarget:=sCtrl.rChanU + rRealPos,
								rFeedback:=rRealPos,
								rPosLimPositive:=sCtrl.rSoft_limit_Postive,
								rPosLimNegative:=sCtrl.rSoft_limit_Negative,
								rVelLim:=sCtrl.rVel_Limit,
								rKp:=sCtrl.rP_AutoTrack,//自跟踪PI系数3,0.02
								rKi:=sCtrl.rI_AutoTrack,
								rKd:=sCtrl.rD,
								bPIDEnable:=sCtrl.bPIDEnable,
								iThreshold:= -1,
								rPIDOutput=>sCtrl.rPIDCmdVel);	
								*)
						vpid1(rKpbase:=Persistentvars.rElKpBase, rKibase:=Persistentvars.rElKiBase, rKpMax:=Persistentvars.rElKpMax, rKiMax:=Persistentvars.rElKiMax, rVelThreshold:=Persistentvars.rElThre,rTarget:=sCtrl.rPIDCmdPos,rFeedback:=rRealPos,rPosLimPositive:=sCtrl.rSoft_limit_Postive,
							rPosLimNegitive:=sCtrl.rSoft_limit_Negative,
								bPIDEnable:=sCtrl.bPIDEnable,rVelLim:=sCtrl.rVel_Limit,rKpScale:=Persistentvars.rElKpscale,rKiScale:=Persistentvars.rElKiscale,rElPos:=GVL.rFctPosReal_1-90,
								iThrehold:=sCtrl.rPIDThre,rPIDOutDir=>sCtrl.rPIDCmdVel);						
					ELSE
						//PID计算速度指令
						(*
						VelPID_3(rTarget:=sCtrl.rPIDCmdPos,
							rFeedback:=rRealPos,
							rVelLim:=sCtrl.rVel_Limit,
							rPosLimPositive:=sCtrl.rSoft_limit_Postive,
							rPosLimNegative:=sCtrl.rSoft_limit_Negative,
							rKp:=sCtrl.rP,//程引PI系数地带：1,0.002  高带：3,0.02
							rKi:=sCtrl.rI,
							rKd:=sCtrl.rD,
							bPIDEnable:=sCtrl.bPIDEnable,
							iThreshold:=sCtrl.rPIDThre,
							rPIDOutput=>);
							*)
						vpid1(rKpbase:=Persistentvars.rElKpBase, rKibase:=Persistentvars.rElKiBase, rKpMax:=Persistentvars.rElKpMax, rKiMax:=Persistentvars.rElKiMax, rVelThreshold:=Persistentvars.rElThre,rTarget:=sCtrl.rPIDCmdPos,rFeedback:=rRealPos,rPosLimPositive:=sCtrl.rSoft_limit_Postive,
							rPosLimNegitive:=sCtrl.rSoft_limit_Negative,
								bPIDEnable:=sCtrl.bPIDEnable,rVelLim:=sCtrl.rVel_Limit,rKpScale:=Persistentvars.rElKpscale,rKiScale:=Persistentvars.rElKiscale,rElPos:=GVL.rFctPosReal_1-90,
								iThrehold:=sCtrl.rPIDThre,rPIDOutDir=>sCtrl.rPIDCmdVel);
					END_IF
					GVL.diElTargetVel := REAL_TO_DINT(sCtrl.rPIDCmdVel * 524288 / 360);
					GVL.diElTargetAcc := REAL_TO_UDINT(sCtrl.rAcceleration * 524288 / 360);   //加速度
					GVL.diElTargetDec := REAL_TO_UDINT(sCtrl.rDeceleration * 524288 / 360);   //减速度
				END_IF
			MODES.reset://重置
				IF NOT sStatus.Disabled THEN
					IF sStatus.Moving THEN
						GVL.diElTargetVel := 0;
						bElCtrlBit8 := TRUE;
					ELSE
						bElCtrlBit8 := FALSE;
					END_IF
				END_IF
			MODES.halt://待机
				IF NOT sStatus.Disabled THEN
					IF sStatus.Moving THEN
						GVL.diElTargetVel := 0;
						bElCtrlBit8 := TRUE;
					ELSE
						bElCtrlBit8 := FALSE;
					END_IF
				END_IF

		END_CASE
	ELSE // 本控
		IF sLocal.iMode <> 1 THEN
			istate:=0;
			icount:=0;
		END_IF
		CASE sLocal.iMode OF
			MODES.powerOff: // 下电
				IF NOT sStatus.Disabled THEN
					IF sStatus.Moving THEN // 运动中，先停止运动
						GVL.diElTargetVel := 0;
						bElCtrlBit8 := TRUE;
					ELSE
						// 写入下电控制字
						GVL.bElCtrlBit3 := FALSE;
						GVL.bElCtrlBit0 := FALSE;
						GVL.bElCtrlBit1 := FALSE;
						GVL.bElCtrlBit2 := FALSE;
					END_IF
				END_IF
			MODES.powerOn:  // 上电
				IF sStatus.Disabled THEN
					// 目标速度清零
					GVL.diElTargetVel := 0;
					IF GVL.siElMode <> 3 THEN // 上电时模式默认为3，速度模式
						GVL.siElMode := 3;
					END_IF
					IF siElMode = 3 THEN



						CASE istate OF
							0:
								GVL.bElCtrlBit1 := TRUE;
								GVL.bElCtrlBit2 := TRUE;
								icount := icount + 1;
								IF icount = 20 THEN
									icount:=0;
									istate:=1;
								END_IF
							1:
								GVL.bElCtrlBit0 := TRUE;
								icount := icount + 1;
								IF icount = 20 THEN
									icount:=0;
									istate:=2;
								END_IF
							2:
								GVL.bElCtrlBit3 := TRUE;
						END_CASE
					END_IF
				ELSE
					IF sStatus.Moving THEN
						GVL.diElTargetVel := 0;
						bElCtrlBit8 := TRUE;
					ELSE
						bElCtrlBit8 := FALSE;
					END_IF
				END_IF
			MODES.velocityMode://手控速度模式-本控模式
				IF NOT sStatus.Disabled THEN
					IF ABS(sLocal.rVelCmd) <= sLocal.rVel_Limit THEN
						GVL.diElTargetVel := REAL_TO_DINT(sLocal.rVelCmd * 524288 / 360);
					ELSIF sLocal.rVelCmd > sLocal.rVel_Limit THEN
						GVL.diElTargetVel := REAL_TO_DINT(sLocal.rVel_Limit * 524288 / 360);
					ELSE
						GVL.diElTargetVel := REAL_TO_DINT(-sLocal.rVel_Limit * 524288 / 360);
					END_IF
					GVL.diElTargetAcc := REAL_TO_UDINT(sLocal.rAcceleration * 524288 / 360);   //加速度
					GVL.diElTargetDec := REAL_TO_UDINT(sLocal.rDeceleration * 524288 / 360);   //减速度
				END_IF
			MODES.programBootMode://本控位置模式
				IF NOT sStatus.Disabled THEN
					IF NOT sLocal.bPIDEnable THEN
						GVL.diElTargetVel := 0;							
					ELSE
						IF NOT slocal.bStartAutoTrack THEN
							//PID计算速度指令
							 VelPID_2(rTarget:=sLocal.rPosCmd,
									 rFeedback:=rRealPos,
									 rPosLimPositive:=sLocal.rSoft_limit_Postive,//软限位
									 rPosLimNegative:=sLocal.rSoft_limit_Negative,
									 rKp:=0.7,
									 rKi:=0,
									 rKd:=0,
									 iThreshold:=sLocal.rPIDThre,
									 bPIDEnable:=sLocal.bPIDEnable,
									 rVelLim:=sLocal.Pos_Vel,
									 rPIDOutput=>sLocal.rPIDCmdVel);//普通PID
						ELSE
							 VelPID_2(rTarget:=sLocal.rChanU + rRealPos,
								rFeedback:=rRealPos,
								rPosLimPositive:=sLocal.rSoft_limit_Postive,
								rPosLimNegative:=sLocal.rSoft_limit_Negative,
								rVelLim:=sLocal.rVel_Limit,
								rKp:=1,//自跟踪PI系数3,0.02
								rKi:=0,
								rKd:=0,
								bPIDEnable:=sLocal.bPIDEnable,
								iThreshold:= -1,
								rPIDOutput=>sLocal.rPIDCmdVel);
						END_IF

					END_IF
					GVL.diElTargetVel := REAL_TO_DINT(sLocal.rPIDCmdVel * 524288 / 360);
					GVL.diElTargetAcc := REAL_TO_UDINT(9 * 524288 / 360);   //加速度
					GVL.diElTargetDec := REAL_TO_UDINT(9 * 524288 / 360);   //减速度
				END_IF
			MODES.reset://重置
			// 是否需要
			MODES.halt://待机
				IF NOT sStatus.Disabled THEN
					IF sStatus.Moving THEN
						GVL.diElTargetVel := 0;
						bElCtrlBit8 := TRUE;
					ELSE
						bElCtrlBit8 := FALSE;
					END_IF
				END_IF

		END_CASE
	END_IF
ELSIF GVL.Error_code<>0 AND GVL.eElErrorcode = 0 AND NOT GVL.bElCtrlBit7  AND NOT tr AND NOT bfin1 AND NOT bfin2 THEN
	// 出现错误，轴停止运动
	GVL.diElTargetVel := 0;
	bElCtrlBit8 := TRUE;
	TON_0(IN:=bElCtrlBit8,PT:=T#1S,Q=>,ET=>);//判断stop0执行是否超时,若超时强制下电（手动复位）
	IF TON_0.Q THEN
		bTick:=TRUE;
	END_IF
	IF bTick AND sStatus.Moving THEN // 超时强制下电
		// 写入下电控制字
		GVL.bElCtrlBit3 := FALSE;
		GVL.bElCtrlBit0 := FALSE;
		GVL.bElCtrlBit1 := FALSE;
		GVL.bElCtrlBit2 := FALSE;
	END_IF
END_IF

baseline.declaration:
PROGRAM Modbus_Slave
