	rVelcmd_2 			:REAL; 			//轴2速度指令远控
	rP_2 				:REAL;  		//轴2P远控
	rI_2 			 	:REAL;  		//轴2I远控
	rD_2 			 	:REAL;  		//轴2D远控
	rThreshold_2 		:INT;			//轴2积分阈值远控
	rAcceleration_2 	:REAL;			//最大加速度
	rDeceleration_2  	:REAL;			//最大减速度	
